{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Defibrotide had an absolute oral bioavailability of 2.6–13% in patients after an oral 423 mg dose versus IV, which is below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Chrysin oral bioavailability was estimated at 0.003–0.02% in healthy volunteers after a 400 mg oral dose, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Aspirin absolute bioavailability was 65–75% in 4 subjects given 650 mg as an oral solution, which is above the 20% threshold and is the main contradictory record.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Most high-assay-transfer evidence molecules show absolute oral bioavailability well below 20%, including direct numeric measurements of 0.003–0.02%, 2.6–13%, and ~11%. The single contradictory aspirin record is offset by its formulation-dependent and measurement-dependent inconsistencies, so the overall prediction is low.",
  "evidence_gaps": [
    "Aspirin has conflicting records depending on formulation and whether parent drug or total salicylate is measured, adding uncertainty to the contradictory high-F value.",
    "Several records are qualitative or report systemic availability rather than explicit absolute oral bioavailability, though the strongest numeric records support low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

